import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './Prediction.css';

const questions = [
  { key: 'age', question: "Hey! 👋 How old are you?", type: 'number', min: 0, max: 120 },
  { key: 'gender', question: "What's your gender? (Female, Male, Other)", type: 'options', options: ['Female', 'Male', 'Other'] },
  { key: 'bmi', question: "What’s your Body Mass Index (BMI)?", type: 'number', min: 10, max: 50 },
  { key: 'hbA1c_level', question: "Got your HbA1c level (%)?", type: 'number', min: 3, max: 15 },
  { key: 'blood_glucose_level', question: "And your Blood Glucose Level (mg/dL)?", type: 'number', min: 50, max: 300 },
  { key: 'hypertension', question: "Do you have hypertension? (yes/no)", type: 'boolean' },
  { key: 'heart_disease', question: "Do you have any heart disease? (yes/no)", type: 'boolean' },
  { key: 'smoking_history', question: "What’s your smoking history? (never, former, current, not current, ever)", type: 'options', options: ['never', 'former', 'current', 'not current', 'ever'] },
];

function Prediction() {
  const [messages, setMessages] = useState([{ from: 'bot', text: "Yo! I got you. Let’s get started 🚀\n" + questions[0].question }]);
  const [currentStep, setCurrentStep] = useState(0);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [answers, setAnswers] = useState({});
  const [prediction, setPrediction] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const addMessage = (from, text) => {
    setMessages(prev => [...prev, { from, text }]);
  };

  const validateInput = (value) => {
    const q = questions[currentStep];
    if (q.type === 'number') {
      const n = Number(value);
      return !isNaN(n) && n >= q.min && n <= q.max;
    }
    if (q.type === 'boolean') {
      return ['yes', 'no'].includes(value.toLowerCase());
    }
    if (q.type === 'options') {
      return q.options.includes(value);
    }
    return false;
  };

  const handleUserInput = async () => {
    const value = inputValue.trim();
    if (!validateInput(value)) {
      addMessage('bot', "🤔 Hmm, that doesn't look right. Can you try again?");
      return;
    }

    addMessage('user', value);

    const q = questions[currentStep];
    let val = value;
    if (q.type === 'number') val = Number(val);
    if (q.type === 'boolean') val = val.toLowerCase() === 'yes' ? 1 : 0;

    const newAns = { ...answers, [q.key]: val };
    setAnswers(newAns);
    setInputValue('');

    if (currentStep + 1 < questions.length) {
      setTimeout(() => {
        addMessage('bot', questions[currentStep + 1].question);
        setCurrentStep(currentStep + 1);
      }, 800);
    } else {
      setIsLoading(true);
      setTimeout(async () => {
        try {
          const res = await axios.post('http://localhost:8000/predict', newAns);
          const pred = res.data;
          addMessage('bot', `🧠 Prediction: ${pred.interpretation} (${(pred.probability * 100).toFixed(1)}%)`);
          addMessage('bot', pred.prediction
            ? "⚠️ You should totally check in with your doc for more info."
            : "🎉 You're good! Just keep up the healthy vibes!");
          setPrediction(pred);
        } catch {
          addMessage('bot', "💥 Oops, something broke. Wanna try again later?");
        } finally {
          setIsLoading(false);
        }
      }, 1200);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !isLoading) handleUserInput();
  };

  const renderInput = () => {
    const q = questions[currentStep];
    if (q.type === 'options') {
      return (
        <select value={inputValue} onChange={e => setInputValue(e.target.value)} disabled={isLoading}>
          <option value="">-- Select --</option>
          {q.options.map(opt => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      );
    }
    return (
      <input
        type={q.type === 'number' ? 'number' : 'text'}
        placeholder="Type here..."
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={handleKeyPress}
        disabled={isLoading}
        autoFocus
      />
    );
  };

  return (
    <div className="chatbot-container">
      <h2 className="title">🩺 Diabetes Risk ChatBot</h2>
      <div className="chat-window">
        {messages.map((msg, i) => (
          <div key={i} className={`chat-msg ${msg.from}`}>
            <div className="msg-bubble">{msg.text}</div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {!prediction && (
        <div className="input-area">
          {renderInput()}
          <button onClick={handleUserInput} disabled={isLoading || inputValue.trim() === ''}>
            {isLoading ? '...' : '➤'}
          </button>
        </div>
      )}

      {prediction && (
        <button className="restart-btn" onClick={() => {
          setMessages([{ from: 'bot', text: "Yo! I got you. Let’s get started 🚀\n" + questions[0].question }]);
          setCurrentStep(0);
          setAnswers({});
          setPrediction(null);
          setInputValue('');
        }}>
          🔁 Start Over
        </button>
      )}
    </div>
  );
}

export default Prediction;
